contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(true);
        bool reverted;
        try c.transfer(from, caddress, _tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // General rule: transfer reverts iff _tos.length == 0; otherwise it returns true (i.e., did not revert).
        assert((!reverted && _tos.length > 0) || (reverted && _tos.length == 0));
    }
    receive() external payable {}
}

