    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        // Restrict to exactly one recipient to simplify reasoning
        require(_tos.length == 1);
        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }
        // General rule: when the call does not revert, it must return true.
        assert(reverted || ret == true);
    }
    receive() external payable {}
}

